import java.io.*;import java.util.*;import java.util.stream.*;class Result{public static int unboundedKnapsack(int k,List<Integer> arr){boolean[] reachable=new boolean[k+1];reachable[0]=true;for(int val:arr){if(val<=0)continue;for(int i=val;i<=k;i++){if(reachable[i-val])reachable[i]=true;}}for(int i=k;i>=0;i--){if(reachable[i])return i;}return 0;}}public class Solution{public static void main(String[] args) throws IOException{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));BufferedWriter bw=new BufferedWriter(new OutputStreamWriter(System.out));int t=Integer.parseInt(br.readLine().trim());for(int caseNum=0;caseNum<t;caseNum++){String[] nk=br.readLine().trim().split("\\s+");int n=Integer.parseInt(nk[0]);int k=Integer.parseInt(nk[1]);List<Integer> arr=new ArrayList<>();String[] parts=br.readLine().trim().split("\\s+");for(int i=0;i<n && i<parts.length;i++){arr.add(Integer.parseInt(parts[i]));}int result=Result.unboundedKnapsack(k,arr);bw.write(String.valueOf(result));bw.newLine();}bw.flush();br.close();bw.close();}}